Script:
UserOnboardingAdmin = {
	states: {
		"New": "[resource_displayname[New]]",
		"Rejected": "[resource_displayname[rejected]]",
		"Pending": "[resource_displayname[pending]]",
		"AdminRejected": "[resource_displayname[adminRejected]]",
		"Accepted": "[resource_displayname[accepted]]"
	},

	iconStates: {
		"New": "k-i-file",
		"Accepted": "k-i-file-add",
		"Pending": "k-i-file-config",
		"Rejected": "k-i-file-error"
	},

	requestTypes: {
		"buyer": "[resource_displayname[buyer]]",
		"supplierreadonly": "[resource_displayname[supplierreadonly]]",
		"supplieralacarte": "[resource_displayname[supplieralacarte]]",
		"funder": "[resource_displayname[funder]]"
	},

	init: async function (app, container) {
		app = app || session.app;
		container = container || $(".component[name=UserOnboardingAdmin]");
        api.addToMetaCache([
            {
        "Name": "Core",
        "Types": [
            [meta[Core/Submission]]
        ]
    }
        ]);
		var dataSource = await model.getDatasource({
			endpoint: "ContentManagement/Submission",
			odataAppend: "?$filter=SourceComponent eq 'UserOnboarding' and State eq 'new' and AppId eq " + app.Id
		});
		var grid = await [script[UserOnboardingAdminGrid]]({ element: $("[name=userOnboardingGrid]", container), dataSource: dataSource });
		grid.detailTemplate = "<div name='newRequestDialog'>" + $("[name=viewRequest").html() + "</div>";
		grid.detailExpand = async (e) => { await UserOnboardingAdmin.viewRequest(e, app, grid); };
		await grid.init();
		$("[name=addUserOnboardingRequest]", grid.gridElement).on("click", async (e) => await UserOnboardingAdmin.addUserOnboardingRequest(e, app, grid));
	},

	addUserOnboardingRequest: async function (e, app, grid) {
		var newRequestForm = new Dialog({ title: "[resource_displayname[NewAccessRequest]]", width: 850 });
		newRequestForm.template = $("[name=userOnboardingNewRequestWizardComponent]").first().html();
		newRequestForm.init();
        UserOnboardingNewRequestWizard.init(app, newRequestForm.element, grid, newRequestForm);
	},

	submitRequest: async function (e, app, grid, model) {
		e.preventDefault();
		var submission = { SourceComponent: "UserOnboarding", State: "New", DataJson: JSON.stringify({ "fields": JSON.parse(JSON.stringify(model)) }), AppId: app.Id };
		await api.add("ContentManagement/Submission", submission);
		notification.success("[resource_displayname[SubmissionSubmitted]]");
		grid.refresh();
	},

	viewRequest: async function (e, app, grid) {
		if (!$($(e.detailRow)).attr("expanded")) {
			$($(e.detailRow)).attr("expanded");
			var submission = grid.kendoObject.dataItem(e.masterRow);
			var formData = JSON.parse(submission.DataJson).fields;
			var model = new kendo.observable(formData);
			kendo.bind($(e.detailRow), model);
			var countries = await api.get("B2B/Country");
			$("input[name=country]", $(e.detailRow)).kendoDropDownList({ dataSource: countries.value, dataValueField: "Id", dataTextField: "Name" });
			$("select", $(e.detailRow)).kendoDropDownList();
			$("button[name=approve]", $(e.detailRow)).off("click").on("click", async (e) => { await UserOnboardingAdmin.acceptRequest(e, app, grid, submission); });
			$("button[name=reject]", $(e.detailRow)).off("click").on("click", async (e) => { await UserOnboardingAdmin.rejectRequest(e, app, grid, submission); });
			$("button[name=pending]", $(e.detailRow)).off("click").on("click", async (e) => { await UserOnboardingAdmin.pendingRequest(e, app, grid, submission); });
			$("[name=save]", $(e.detailRow)).off("click").on("click", async (e) => { await UserOnboardingAdmin.saveRequest(e, grid, submission, model); });
		}
	},

	saveRequest: async function (e, grid, submission, model) {
		e.preventDefault();
		notification.success("[resource_displayname[saved]]");
		submission.DataJson = JSON.stringify({ fields: JSON.parse(JSON.stringify(model)) });
		delete submission.type;
		await api.update("ContentManagement/Submission(" + submission.Id + ")", submission);
		grid.kendoObject.dataSource.read();
	},

	acceptRequest: async function (e, app, grid, submission) {
		e.preventDefault();
		var acceptWizardDialog = new Dialog({ title: "[resource_displayname[AcceptRequest]]", height: 520, width: 975 });

		acceptWizardDialog.init(async () => {
			var c = await loadComponent(acceptWizardDialog.element, "UserOnboardingAcceptWizard");
			c.init(app, acceptWizardDialog.element, grid, submission, acceptWizardDialog)
		})
	},

	rejectRequest: async function (e, app, grid, submission) {
		e.preventDefault();
		submission.State = "Rejected";
		delete submission.type;
		var rejectReasonDialog = new Dialog({ title: "[resource_displayname[rejectreason]]" });
		rejectReasonDialog.template = $("script[name=rejectReason]").html();
		rejectReasonDialog.events.reject = async function (e) {
			await api.update("ContentManagement/Submission(" + submission.Id + ")", submission);
			grid.kendoObject.dataSource.read();
			var workflowData = { SubmissionId: submission.Id, RejectReason: $("input[name=rejectReason]", rejectReasonDialog.element).val() };
			var rejectWorkflow = await api.get("Workflow/FlowDefinition?$filter=Name eq 'OnboardingReject' and AppId eq " + app.Id);
			await api.add("Workflow/FlowDefinition(" + rejectWorkflow.value[0].Id + ")/Execute()", workflowData).then(() => { notification.success("[resource_displayname[executed]]"); rejectReasonDialog.events.close(); });
		};
		rejectReasonDialog.init();
	},

	pendingRequest: async function(e, app, grid,submission) {
		e.preventDefault();
		submission.State = "Pending";
		grid.kendoObject.dataSource.read();
	}
}
